# Example output:
    # <AGENTOPS_DEBUG_OUTPUT>
    # on_llm_start called with arguments:
    # run_id: UUID('5fda42fe-809b-4179-bad2-321d1a6090c7')
    # parent_run_id: UUID('63f1c4da-3e9f-4033-94d0-b3ebed06668f')
